#!/usr/bin/env bash
## Usage: bench/slow-load.sh --workload <http|sse> [--users <n>] [--quick] [--label <text>]
## Measures what slow requests do to a light request on the active server and its current worker setting.
## The load holds <n> users (default 100 for http, 30 for sse) open in a closed loop:
##   http  GET /listings/1/slow (about 300 ms in the VIN stub), generated by oha;
##   sse   GET /listings/{id}/describe (a fake stream of 120 tokens at 50 ms, about 6 s), id rotating over 1..50000, read to
##         data: [DONE] by bench/k6-sse.js; the load figures are the time to [DONE], streams per second and the non-200 or incomplete share.
## At the same time a probe asks GET /healthz at a steady 5 requests per second with a 10 s timeout and records
## its latency and errors. It opens 50 connections (5 per second x 10 s), so a stuck request never stops the
## schedule, and oha's --latency-correction counts the wait of a late request (coordinated omission). health_p95_ms is
## computed over all sent probes, a timeout counting as the 10 s timeout value; health_p95_answered_ms covers the
## answered ones only and is null (starved: true) when nothing answered. The load and the probe are two separate one-off containers on ddev_default, each capped
## at 2 CPUs and reaching the DDEV router through --add-host; the stub VIN service is its own DDEV service.
## Default method: warm-up 30 s (load only), measure 60 s, 3 repeats. --quick (development only): warm-up 5 s,
## measure 15 s, 1 repeat, no restart, and no clean-git-tree check.
## The harness sets .env to APP_ENV=production, APP_DEBUG=false, DEBUG_ROUTES=true (sse also AI_PROVIDER=fake-stream, AI_FAKE_TOKENS=120, AI_FAKE_TOKEN_DELAY_MS=50 and a high
## AI_DESCRIBE_PER_MINUTE), runs `artisan optimize`, checks the run conditions (exit 2 naming the failed check,
## before any load) and restores .env on exit.
## Output: bench/results/slow-load/<UTC date>/<workload>-<label>.json (--quick: the gitignored bench/results/raw/)
## with metadata, every repeat, the medians and the spreads, and a table on stdout. A health p95 spread above 20 % is flagged in both.
## Listing ids rotate: ID_OFFSET is 0 in a warm-up and repeat r x 10007 (mod 50000) in the measure window of repeat r.
##   http: oha reads a list of 2000 consecutive ids starting at the offset (--urls-from-file; oha picks from the list);
##   sse:  k6 starts its id counter at the offset.
## The slow route is behind DEBUG_ROUTES and the `slow` limiter (VINSTUB_PER_MINUTE); the harness sets both in .env (http).
## Env: BENCH_WARMUP, BENCH_MEASURE (seconds), BENCH_REPEATS, BENCH_SETTLE (seconds after restart),
##      BENCH_APPROOT (project root), BENCH_BASE_URL (default: `ddev server --url`), BENCH_OUT_DIR,
##      BENCH_READY_TIMEOUT (seconds to wait for /healthz after a worker-server reload, default 120),
##      BENCH_OHA_IMAGE, BENCH_K6_IMAGE.

set -Eeuo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APPROOT="${BENCH_APPROOT:-$(cd "$SCRIPT_DIR/.." && pwd)}"
SITE="${DDEV_SITENAME:-ai-lab}"
OHA_IMAGE="${BENCH_OHA_IMAGE:-ai-lab-oha:1.16.0}"   # built locally from bench/oha/Dockerfile
K6_IMAGE="${BENCH_K6_IMAGE:-grafana/k6:1.0.0}"
source "$SCRIPT_DIR/lib/health-probe.sh"
SPREAD_LIMIT=20
ID_STEP=10007
ID_SPAN=50000
ID_LIST=2000
LISTING_ID=1

usage() {
  echo "Usage: $0 --workload <http|sse> [--users <n>] [--quick] [--label <text>]" >&2
  exit 2
}

workload=""
users=""
quick=0
label="cell"
while [[ $# -gt 0 ]]; do
  case "$1" in
    --workload) workload="${2:-}"; shift 2 || usage ;;
    --users) users="${2:-}"; shift 2 || usage ;;
    --quick) quick=1; shift ;;
    --label) label="${2:?--label needs a value}"; shift 2 ;;
    *) usage ;;
  esac
done
[[ "$workload" == "http" || "$workload" == "sse" ]] || usage
if [[ -z "$users" ]]; then
  if [[ "$workload" == "http" ]]; then users=100; else users=30; fi
fi
[[ "$users" =~ ^[1-9][0-9]*$ ]] || usage
[[ "$label" =~ ^[a-z0-9-]+$ ]] || { echo "Invalid --label '$label': use a-z, 0-9 and -." >&2; exit 2; }

if [[ "$quick" == "1" ]]; then
  WARMUP="${BENCH_WARMUP:-5}"
  MEASURE="${BENCH_MEASURE:-15}"
  REPEATS="${BENCH_REPEATS:-1}"
  SETTLE="${BENCH_SETTLE:-0}"
else
  WARMUP="${BENCH_WARMUP:-30}"
  MEASURE="${BENCH_MEASURE:-60}"
  REPEATS="${BENCH_REPEATS:-3}"
  SETTLE="${BENCH_SETTLE:-10}"
fi

[[ "$REPEATS" =~ ^[1-9][0-9]*$ ]] || { echo "BENCH_REPEATS must be a positive integer (got '$REPEATS')." >&2; exit 2; }

cd "$APPROOT"
ENV_FILE="$APPROOT/.env"
BACKUP="$APPROOT/.env.bench-backup"
WORK="$(mktemp -d)"
RUN_ID="$$"
LOAD_NAME="slow-load-load-$RUN_ID"
PROBE_NAME="slow-load-probe-$RUN_ID"
env_switched=0
worker_restarted=0

restore_env() {
  docker rm -f "$LOAD_NAME" "$PROBE_NAME" >/dev/null 2>&1 || true
  if [[ "$env_switched" == "1" && -f "$BACKUP" ]]; then
    cp -p "$BACKUP" "$ENV_FILE"
    rm -f "$BACKUP"
    ddev artisan optimize:clear >/dev/null 2>&1 || true
    # Worker servers keep the benchmark config in memory until they boot again.
    if [[ "$worker_restarted" == "1" ]]; then
      ddev restart >/dev/null 2>&1 || true
    fi
  fi
  rm -rf "$WORK"
}
trap restore_env EXIT
trap 'exit 130' INT TERM

refuse() {
  echo "Run condition failed: $1" >&2
  exit 2
}

set_env_value() {
  local key="$1" value="$2"
  { grep -v "^${key}=" "$ENV_FILE" || true; echo "${key}=${value}"; } > "$WORK/env.new"
  cat "$WORK/env.new" > "$ENV_FILE"
}

if [[ -e "$BACKUP" ]]; then
  echo "Stale $BACKUP exists: a previous run did not restore .env. Restore it by hand first." >&2
  exit 2
fi
[[ -f "$ENV_FILE" ]] || { echo "No .env at $ENV_FILE" >&2; exit 2; }

server="$(ddev server --current)"
BASE_URL="${BENCH_BASE_URL:-$(ddev server --url)}"
HOST="${BASE_URL#*://}"
HOST="${HOST%%/*}"
HOST_NAME="${HOST%%:*}"

cp -p "$ENV_FILE" "$BACKUP"
env_switched=1
set_env_value APP_ENV production
set_env_value APP_DEBUG false
set_env_value DEBUG_ROUTES true
if [[ "$workload" == "http" ]]; then
  # The slow route holds a worker on purpose: it needs DEBUG_ROUTES and a limit far above the load's request rate.
  set_env_value VINSTUB_PER_MINUTE 1000000
fi
if [[ "$workload" == "sse" ]]; then
  set_env_value AI_PROVIDER fake-stream
  set_env_value AI_FAKE_TOKENS 120
  set_env_value AI_FAKE_TOKEN_DELAY_MS 50
  set_env_value AI_DESCRIBE_PER_MINUTE 1000000
fi
ddev artisan optimize >/dev/null

# Worker servers boot the app once: reload them so the switched .env and the caches are what they serve.
READY_TIMEOUT="${BENCH_READY_TIMEOUT:-120}"
if [[ "$server" == "frankenphp-octane" || "$server" == "frankenphp-worker" ]]; then
  ddev restart >/dev/null
  worker_restarted=1
  ready_deadline=$((SECONDS + READY_TIMEOUT))
  until [[ "$(curl -ksS --max-time 10 -o /dev/null -w '%{http_code}' "$BASE_URL/healthz" 2>/dev/null || true)" == "200" ]]; do
    [[ "$SECONDS" -lt "$ready_deadline" ]] || refuse "$server did not answer /healthz with 200 within ${READY_TIMEOUT}s after the restart"
    sleep 1
  done
fi

check_conditions() {
  local value body status
  [[ "$(ddev artisan config:show app.env | awk 'NF {print $NF}')" == "production" ]] || refuse "APP_ENV is not production"
  [[ "$(ddev artisan config:show app.debug | awk 'NF {print $NF}')" == "false" ]] || refuse "APP_DEBUG is not false"
  ddev exec ls bootstrap/cache/config.php >/dev/null 2>&1 || refuse "config cache is not built"
  ddev exec sh -c 'ls bootstrap/cache/routes*.php' >/dev/null 2>&1 || refuse "route cache is not built"
  ddev exec sh -c 'ls storage/framework/views/*.php' >/dev/null 2>&1 || refuse "view cache is not built"
  body="$WORK/check.json"
  status="$(curl -ksS --max-time 30 -o "$body" -w '%{http_code}' "$BASE_URL/healthz")" || status=000
  [[ "$status" == "200" ]] || refuse "cannot read /healthz (status $status)"
  if [[ "$workload" == "http" ]]; then
    status="$(curl -ksS --max-time 30 -H 'Accept: application/json' -o "$body" -w '%{http_code}' "$BASE_URL/listings/$LISTING_ID/slow")" || status=000
    [[ "$status" == "200" ]] || refuse "cannot read /listings/$LISTING_ID/slow (status $status): is the vinstub service running?"
  fi
  status="$(curl -ksS --max-time 30 -H 'Accept: application/json' -o "$body" -w '%{http_code}' "$BASE_URL/debug/runtime")" || status=000
  [[ "$status" == "200" ]] || refuse "cannot read /debug/runtime (status $status)"
  value="$(jq -r '.data.opcache_enabled' "$body")"
  [[ "$value" == "true" ]] || refuse "OPcache is not on for the serving SAPI"
  value="$(jq -r '.data.xdebug_loaded' "$body")"
  [[ "$value" == "false" ]] || refuse "Xdebug is not off for the serving SAPI"
  if [[ "$quick" == "0" ]]; then
    # .ai/session/ is the SDD tooling's own log, rewritten by the tooling itself; it is not app code.
    value="$(git status --porcelain -- . ':!bench/results' ':!.ai/session' 2>/dev/null || true)"
    [[ -z "$value" ]] || refuse "git working tree has changes outside bench/results/ and .ai/session/"
  fi
}
check_conditions

OHA_DIGEST="$(image_digest "$OHA_IMAGE")"
[[ -n "$OHA_DIGEST" ]] || { echo "Cannot read the digest or ID of $OHA_IMAGE; refusing to run." >&2; exit 1; }
LOAD_IMAGE="$OHA_IMAGE"
LOAD_DIGEST="$OHA_DIGEST"
if [[ "$workload" == "sse" ]]; then
  LOAD_IMAGE="$K6_IMAGE"
  LOAD_DIGEST="$(image_digest "$K6_IMAGE")"
  [[ -n "$LOAD_DIGEST" ]] || { echo "Cannot read the digest or ID of $K6_IMAGE; refusing to run." >&2; exit 1; }
fi

COMMIT="$(git rev-parse --short HEAD 2>/dev/null || echo unknown)"
CONCURRENCY_SETTING="$(bash "$SCRIPT_DIR/concurrency.sh" --show 2>/dev/null | tr '\n' ' ' | sed 's/ *$//' || true)"
[[ -n "$CONCURRENCY_SETTING" ]] || CONCURRENCY_SETTING="default"
DATE="${BENCH_DATE:-$(date -u +%Y-%m-%d)}"
if [[ "$quick" == "1" ]]; then
  OUT_DIR="${BENCH_OUT_DIR:-$APPROOT/bench/results/raw}"
else
  OUT_DIR="${BENCH_OUT_DIR:-$APPROOT/bench/results/slow-load/$DATE}"
fi
mkdir -p "$OUT_DIR"

# Closed-loop load for $1 seconds with the listing ids starting at offset $3; raw JSON goes to $2.
generate_load() {
  local seconds="$1" target="$2" offset="${3:-0}"
  if [[ "$workload" == "http" ]]; then
    awk -v base="$BASE_URL" -v off="$offset" -v span="$ID_SPAN" -v n="$ID_LIST" \
      'BEGIN { for (i = 0; i < n; i++) printf "%s/listings/%d/slow\n", base, (off + i) % span + 1 }' > "$WORK/urls.txt"
    # -w waits for requests still in flight at the deadline instead of counting them as errors.
    docker_run "$LOAD_NAME" -v "$WORK:/ids:ro" "$OHA_IMAGE" -c "$users" -z "${seconds}s" -w -t 30s --no-tui --insecure \
      --output-format json --urls-from-file /ids/urls.txt > "$target"
  else
    rm -f "$WORK/k6.json"
    docker_run "$LOAD_NAME" -v "$SCRIPT_DIR:/bench:ro" -v "$WORK:/out" -e "BASE_URL=$BASE_URL" -e "DURATION=${seconds}s" \
      -e "VUS=$users" -e "ID_OFFSET=$offset" \
      "$K6_IMAGE" run --quiet --summary-export /out/k6.json /bench/k6-sse.js >/dev/null
    [[ -s "$WORK/k6.json" ]] || { echo "k6 wrote no summary." >&2; return 1; }
    cat "$WORK/k6.json" > "$target"
  fi
}

# Reads the k6 summary on stdin. One failure per stream: stream_failed is a Rate added once per iteration (non-200 or no
# [DONE]), so its passes are the failed streams and passes + fails the streams. Times are the time to [DONE] of complete
# streams (stream_done_ms); when none completed they are null and no_stream_completed is true. http_req_duration is never used.
parse_k6() {
  jq '(.metrics.stream_failed // {}) as $f
    | (.metrics.stream_done_ms // null) as $t
    | {
        rps: (.metrics.http_reqs.rate // 0),
        p50_ms: ($t.med // null),
        p95_ms: ($t["p(95)"] // null),
        p99_ms: ($t["p(99)"] // null),
        no_stream_completed: ($t == null),
        requests: (($f.passes // 0) + ($f.fails // 0)),
        errors: ($f.passes // 0),
        error_percent: (($f.value // 0) * 100)
      }'
}

parse_load() {
  if [[ "$workload" == "http" ]]; then parse_oha load; else parse_k6; fi
}

if [[ "$quick" == "0" && "$SETTLE" != "0" && "$worker_restarted" == "0" ]]; then
  ddev restart >/dev/null
fi
sleep "$SETTLE"
lookup_router
check_conditions

repeat_files=()
for repeat in $(seq 1 "$REPEATS"); do
  offset=$((repeat * ID_STEP % ID_SPAN))
  if [[ "$WARMUP" != "0" ]]; then
    generate_load "$WARMUP" "$WORK/warmup.json" 0 >/dev/null
  fi
  generate_load "$MEASURE" "$WORK/load.json" "$offset" &
  load_pid=$!
  probe_status=0
  generate_probe "$MEASURE" "$WORK/probe.json" || probe_status=$?
  load_status=0
  wait "$load_pid" || load_status=$?
  [[ "$probe_status" == "0" ]] || { echo "The health probe failed (exit $probe_status)." >&2; exit 1; }
  [[ "$load_status" == "0" ]] || { echo "The load generator failed (exit $load_status)." >&2; exit 1; }
  file="$WORK/repeat-$repeat.json"
  jq -n --argjson load "$(parse_load < "$WORK/load.json")" --argjson health "$(parse_oha probe < "$WORK/probe.json")" \
    --argjson repeat "$repeat" --argjson offset "$offset" '{repeat: $repeat, id_offset: $offset, load: $load, health: $health}' > "$file"
  repeat_files+=("$file")
done

FILE="$OUT_DIR/$workload-$label.json"
jq -s \
  --arg server "$server" --arg workload "$workload" --arg label "$label" --arg commit "$COMMIT" \
  --arg concurrency "$CONCURRENCY_SETTING" --arg base "$BASE_URL" --arg date "$DATE" \
  --arg loadImage "$LOAD_IMAGE" --arg loadDigest "$LOAD_DIGEST" --arg probeImage "$OHA_IMAGE" --arg probeDigest "$OHA_DIGEST" \
  --argjson users "$users" --argjson probeConnections "$PROBE_CONNECTIONS" --argjson probeQps "$PROBE_QPS" --argjson probeTimeout "$PROBE_TIMEOUT" \
  --argjson warmup "$WARMUP" --argjson measure "$MEASURE" --argjson quick "$quick" --argjson limit "$SPREAD_LIMIT" '
  def nums: map(select(. != null));
  def median: nums | sort | if length == 0 then null elif length % 2 == 1 then .[length / 2 | floor] else (.[length / 2 - 1] + .[length / 2]) / 2 end;
  def spread: nums as $v | ($v | median) as $m
    | if $m == null then null
      elif $m == 0 then (if ($v | max) > 0 then null else 0 end)
      else (($v | max) - ($v | min)) / $m * 100 end;
  def figures: [
    ["load", "rps", (.load.rps)], ["load", "p50_ms", (.load.p50_ms)], ["load", "p95_ms", (.load.p95_ms)],
    ["load", "p99_ms", (.load.p99_ms)], ["load", "errors", (.load.errors)], ["load", "error_percent", (.load.error_percent)],
    ["health", "rps", (.health.rps)], ["health", "p50_ms", (.health.p50_ms)], ["health", "p95_ms", (.health.p95_ms)],
    ["health", "p95_answered_ms", (.health.p95_answered_ms)],
    ["health", "p99_ms", (.health.p99_ms)], ["health", "errors", (.health.errors)], ["health", "error_percent", (.health.error_percent)],
    ["health", "502", (.health.breakdown["502"])], ["health", "504", (.health.breakdown["504"])],
    ["health", "other_5xx", (.health.breakdown.other_5xx)], ["health", "other_non_2xx", (.health.breakdown.other_non_2xx)],
    ["health", "timeouts", (.health.breakdown.timeouts)]
  ] | map({key: "\(.[0])_\(.[1])", value: .[2]});
  . as $repeats
  | ([$repeats[] | figures[]] | group_by(.key) | map({key: .[0].key, values: map(.value)})) as $series
  | ($repeats | map(.health.p95_ms) | spread) as $healthSpread
  | ($repeats | map(.load.rps) | spread) as $loadSpread
  | ($repeats | map(select(.health.starved == true)) | length) as $starvedRepeats
  | ($repeats | map(select(.load.no_stream_completed == true)) | length) as $noStreamRepeats
  | {
      server: $server, workload: $workload, label: $label, commit: $commit, concurrency: $concurrency,
      base_url: $base, date: $date, quick: ($quick == 1),
      users: $users, probe_connections: $probeConnections, probe_qps: $probeQps, probe_timeout_s: $probeTimeout,
      warmup_s: $warmup, measure_s: $measure, repeats: ($repeats | length),
      load_image: $loadImage, load_image_digest: $loadDigest, probe_image: $probeImage, probe_image_digest: $probeDigest,
      health_starved_repeats: $starvedRepeats,
      load_no_stream_repeats: $noStreamRepeats,
      median: (($series | map({key, value: (.values | median)}) | from_entries)
        + {health_starved: ($starvedRepeats > 0), load_no_stream_completed: ($noStreamRepeats > 0)}),
      spread_percent: (($series | map({key, value: (.values | spread)}) | from_entries) + {health_p95: $healthSpread, load_rps: $loadSpread}),
      spread_limit_percent: $limit,
      flagged: ($healthSpread != null and $healthSpread > $limit),
      runs: $repeats
    }' "${repeat_files[@]}" > "$FILE"

echo "workload=$workload server=$server setting=\"$CONCURRENCY_SETTING\" users=$users warmup=${WARMUP}s measure=${MEASURE}s"
{
  printf 'repeat\tload_rps\tload_p95_ms\tload_err_%%\thealth_p95_ms\thealth_p95_answered_ms\thealth_errors\thealth_err_%%\n'
  jq -r 'def r: if . == null then "n/a" else (. * 10 | round / 10 | tostring) end;
    .runs[] | [.repeat, (.load.rps | r), (.load.p95_ms | r), (.load.error_percent | r),
    ((.health.p95_ms | r) + (if .health.starved then " starved" else "" end)), (.health.p95_answered_ms | r), .health.errors, (.health.error_percent | r)] | @tsv' "$FILE"
  jq -r 'def r: if . == null then "n/a" else (. * 10 | round / 10 | tostring) end;
    .median | ["median", (.load_rps | r), (.load_p95_ms | r), (.load_error_percent | r),
    ((.health_p95_ms | r) + (if .health_starved then " starved" else "" end)), (.health_p95_answered_ms | r), .health_errors, (.health_error_percent | r)] | @tsv' "$FILE"
} | awk -F'\t' '{ printf "%-8s %-10s %-12s %-10s %-18s %-24s %-14s %s\n", $1, $2, $3, $4, $5, $6, $7, $8 }'
jq -r '"health breakdown (median) 502=\(.median.health_502) 504=\(.median.health_504) other_5xx=\(.median.health_other_5xx) other_non_2xx=\(.median.health_other_non_2xx) timeouts=\(.median.health_timeouts)"' "$FILE"
jq -r 'if .health_starved_repeats > 0 then "health starved in \(.health_starved_repeats) of \(.repeats) repeats: no probe was answered, health_p95_ms counts the 10 s timeout and health_p95_answered_ms is null" else empty end' "$FILE"
jq -r 'if .load_no_stream_repeats > 0 then "load: no stream completed in \(.load_no_stream_repeats) of \(.repeats) repeats: the time to [DONE] is n/a" else empty end' "$FILE"
jq -r '"health p95 spread " + (if .spread_percent.health_p95 == null then "n/a (median 0)" else "\(.spread_percent.health_p95 | . * 10 | round / 10)%" end) + (if .flagged then " FLAGGED: above \(.spread_limit_percent)%" else " (within \(.spread_limit_percent)%)" end)' "$FILE"
echo "Wrote $FILE"
